## 工具函数测试

纯函数是最容易测试的代码——给定输入，验证输出，无副作用。

```typescript
// src/shared/utils/format.ts
function formatCurrency(amount: number, currency: string = 'CNY'): string {
  return new Intl.NumberFormat('zh-CN', {
    style: 'currency',
    currency,
  }).format(amount);
}

function formatRelativeTime(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMinutes = Math.floor(diffMs / 60000);

  if (diffMinutes < 1) return '刚刚';
  if (diffMinutes < 60) return `${diffMinutes} 分钟前`;
  const diffHours = Math.floor(diffMinutes / 60);
  if (diffHours < 24) return `${diffHours} 小时前`;
  const diffDays = Math.floor(diffHours / 24);
  return `${diffDays} 天前`;
}
```

```typescript
// src/shared/utils/format.test.ts
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { formatCurrency, formatRelativeTime } from './format';

describe('formatCurrency', () => {
  it('should format CNY by default', () => {
    expect(formatCurrency(1234.56)).toBe('¥1,234.56');
  });

  it('should format USD when specified', () => {
    expect(formatCurrency(1234.56, 'USD')).toBe('US$1,234.56');
  });

  it('should handle zero', () => {
    expect(formatCurrency(0)).toBe('¥0.00');
  });

  it('should handle negative numbers', () => {
    expect(formatCurrency(-99.9)).toBe('-¥99.90');
  });
});

describe('formatRelativeTime', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-03-30T12:00:00Z'));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("should return '刚刚' for less than 1 minute", () => {
    const date = new Date('2026-03-30T11:59:30Z');
    expect(formatRelativeTime(date)).toBe('刚刚');
  });

  it('should return minutes for less than 1 hour', () => {
    const date = new Date('2026-03-30T11:30:00Z');
    expect(formatRelativeTime(date)).toBe('30 分钟前');
  });

  it('should return hours for less than 1 day', () => {
    const date = new Date('2026-03-30T06:00:00Z');
    expect(formatRelativeTime(date)).toBe('6 小时前');
  });

  it('should return days for more than 1 day', () => {
    const date = new Date('2026-03-27T12:00:00Z');
    expect(formatRelativeTime(date)).toBe('3 天前');
  });
});
```

